head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[ModelUtil > M > getWorkflow]<br/>ID 를 사용하여 특정 Workflow 객체를 반환합니다.",
    "validation" : [
        "id(필수) 파라미터로 조회할 Workflow 의 ID 를 설정할 수 있어야 합니다.",
        "id 파라미터에 해당하는 Workflow 객체를 반환해야 합니다.",
        "id 파라미터에 해당하는 Workflow 가 없으면 null 을 반환해야 합니다.",
        "XML 에 정의된 Workflow 는 실행 전에도 조회할 수 있어야 합니다.",
        "Workflow 에서 실행이 완료된 Submission 의 실행결과 객체는 반환된 Workflow 객체의 workflowObj.result 로 접근할 수 있어야 합니다."
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// workflow step 의 마지막 function - 완료된 submission 결과(workflowObj.result) 접근 확인
scwin.wf_function_last = function () {
    // 페이지 scope 환경에서는 workflow.id 에 scope prefix(예: 'mf_') 가 붙으므로
    // 실행 중인 workflow 의 full id 를 getRunningWorkflow 로 조회 후 그 id 로 getWorkflow 호출
    var running = WebSquare.ModelUtil.getRunningWorkflow();
    var fullId = running ? running.id : "wf_exam1";

    var wf = WebSquare.ModelUtil.getWorkflow(fullId);
    if (wf) {
        var resultKeys = wf.result ? Object.keys(wf.result) : [];
        wf_body_bottom.getObj("scwin").setReturnValue("[step] function - WebSquare.ModelUtil.getWorkflow('" + fullId + "').result 의 키 목록 : [" + resultKeys.join(", ") + "]");
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue("[step] function - WebSquare.ModelUtil.getWorkflow('" + fullId + "') 반환값 : null");
    }
};

// submission pre / post 함수
scwin.sbm_exam1_pre = function (submissionId, workflowObj) {
    wf_body_bottom.getObj("scwin").setReturnValue("[pre] scwin.sbm_exam1_pre 호출 (submissionId : '" + submissionId + "') → true 반환");
    return true;
};

scwin.sbm_exam1_post = function (submissionObj, workflowObj) {
    wf_body_bottom.getObj("scwin").setReturnValue("[post] scwin.sbm_exam1_post 호출");
};

// workflow 전체 콜백
scwin.wf_resolveCallback = function (wObj) {
    wf_body_bottom.getObj("scwin").setReturnValue("[resolveCallback] workflow 완료");
};

scwin.wf_rejectCallback = function (wObj) {
    wf_body_bottom.getObj("scwin").setReturnValue("[rejectCallback] workflow 오류");
};



scwin.btn_getWorkflow_onclick = function () {
    var scenario = par_scenario.getValue();
    var id = par_id.getValue();

    if (scenario === "1") {
        // 시나리오 1 : XML 정의 workflow 조회 (실행 전)
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 1 : XML 정의 Workflow 를 실행 전에 WebSquare.ModelUtil.getWorkflow('" + id + "') 로 조회 ──");
        var wf = WebSquare.ModelUtil.getWorkflow(id);
        var wfType = (wf === null) ? "null" : (typeof wf);
        var wfId = wf ? wf.id : "-";
        wf_body_bottom.getObj("scwin").setReturnValue("WebSquare.ModelUtil.getWorkflow('" + id + "') → 반환 타입 : " + wfType + " / 반환 객체의 id : " + wfId);
    } else if (scenario === "2") {
        // 시나리오 2 : 실행 후 result 접근
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 2 : WebSquare.ModelUtil.executeWorkflow('" + id + "') 완료 후 WebSquare.ModelUtil.getWorkflow('" + id + "').result 로 완료 submission 결과 조회 ──");
        WebSquare.ModelUtil.executeWorkflow(id);
    } else if (scenario === "3") {
        // 시나리오 3 : 존재하지 않는 ID 조회 → null 반환
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 3 : 존재하지 않는 ID '" + id + "' 로 조회 - null 반환 ──");
        var wfNone = WebSquare.ModelUtil.getWorkflow(id);
        var wfNoneType = (wfNone === null) ? "null" : (typeof wfNone);
        wf_body_bottom.getObj("scwin").setReturnValue("WebSquare.ModelUtil.getWorkflow('" + id + "') → 반환 타입 : " + wfNoneType);
    }
};
